with valid as (select id, email, manager_id, job_title, salary, hire_date, is_remote, level, case when is_remote then 'Yes' else 'No' end as is_remote_label, regexp_replace(email, ' ', '-') as email_slug from employees where is_remote) select e.id, e.manager_id, e.job_title, e.salary, e.hire_date, e.is_remote, e.level, e.email_slug, d.salary as employee_salary, d.hire_date as employee_hire_date from valid e left join employees d on e.manager_id = d.id
